exploreUrl:
@js:
let url = source.key;
let arr = []
let push = (title, url, type) => arr.push({
  title: title,
  url: url,
  style: {
    layout_flexGrow: 1,
    layout_flexBasisPercent: type
  }
})

let res = org.jsoup.Jsoup.parse(java.ajax(url))
res.select('.dispc1 a').forEach(($) => {
    let text = $.text();
    let href = url + $.attr('href');
    push(text, href, 0.25);
});

JSON.stringify(arr)

